//! Rust SDK for the token-rail Service Actor (`service-actor-token-code.fc`,
//! release `tos-service-actor-token-v1`, rail `tos.service.service-actor-token.v1`).
//!
//! The actor keeps the native Service Actor's request lifecycle, terms,
//! attestor and response domain, and prices calls in one recognized token fixed
//! at deploy. A call is funded by an ordinary token transfer whose forward
//! payload is a `token_call`; every token payout is a reported transfer whose
//! outcome comes back to the actor. This module builds the deploy data, the
//! terms and every message, derives the token wallets, and decodes the actor's
//! getters and logs.
use chain_block::{
    BuilderData, Cell, Coins, Deserializable, IBitstring, MsgAddressInt, Serializable, SliceData,
    StateInit, base64_decode, read_single_root_boc,
};
use common::tvm_stack_parser::TvmStackParser;

/// The release build, frozen as `crypto/smartcont/tos-service-actor-token-v1.boc.base64`
/// and checked against its source by `scripts/check-service-actor-bytecode.py`.
pub const SERVICE_ACTOR_TOKEN_CODE_B64: &str = "";

/// The TEST-NETWORK-ONLY build: as the release, with 600-second minimum
/// response and refund windows. Its code hash differs from the release's.
pub const SERVICE_ACTOR_TOKEN_TEST_PROFILE_CODE_B64: &str = "";

/// The rail string manifests and Accepted Quotes name for this actor.
pub const SERVICE_ACTOR_TOKEN_RAIL: &str = "tos.service.service-actor-token.v1";
/// The release name of the frozen build.
pub const SERVICE_ACTOR_TOKEN_RELEASE: &str = "tos-service-actor-token-v1";

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ServiceActorTokenCodeProfile {
    Release,
    TestProfile,
}

impl ServiceActorTokenCodeProfile {
    pub const fn code_b64(self) -> &'static str {
        match self {
            Self::Release => SERVICE_ACTOR_TOKEN_CODE_B64,
            Self::TestProfile => SERVICE_ACTOR_TOKEN_TEST_PROFILE_CODE_B64,
        }
    }

    pub const fn min_window_secs(self) -> u32 {
        match self {
            Self::Release => protocol_constants::MIN_RESPONSE_SLA_SECS,
            Self::TestProfile => protocol_constants::TEST_PROFILE_MIN_WINDOW_SECS,
        }
    }
}

